  }
  .callout.warning { background: #fffbeb; border-color: #fde68a; border-left-color: var(--warning); color: #92400e; }
  .callout.success { background: #f0fdf4; border-color: #bbf7d0; border-left-color: var(--success); color: #14532d; }
  /* FOOTER */
  .report-footer {
