  .exec-block { background: var(--card); border: 1px solid var(--border); border-radius: 10px; padding: 16px; }
  .exec-block h4 { font-size: 0.78rem; font-weight: 700; color: var(--muted); text-transform: uppercase; letter-spacing: 0.06em; margin-bottom: 10px; }
  .exec-block p { font-size: 0.86rem; color: #334155; }
  .tag-cloud { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 12px; }
